compile.workshop:
variables {
    global:
        0: g
        1: v
        2: n
    player:
        0: ps
        1: pv
}

rule ("Initialize global variables") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, Custom String(""));
        Set Global Variable(v, Vector(0, 0, 0));
    }
}

rule ("Initialize player variables") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Player Variable(Event Player, ps, Custom String(""));
        Set Player Variable(Event Player, pv, Vector(0, 0, 0));
    }
}

//Optimize for size enabled
rule ("rule bodies keep size rewrites") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(n, Null);
        Set Global Variable(g, Char In String(Empty Array, False));
        Set Global Variable(v, Add(Left, Right));
    }
}

